import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;import java.io.PrintWriter;import java.io.BufferedOutputStream;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));String line = br.readLine();if (line == null) return;int t = Integer.parseInt(line.trim());while (t-- > 0) {int n = Integer.parseInt(br.readLine().trim());int[] a = new int[n];StringTokenizer st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {a[i] = Integer.parseInt(st.nextToken());}int[] b = new int[n];st = new StringTokenizer(br.readLine());boolean has0 = false;boolean has1 = false;for (int i = 0; i < n; i++) {b[i] = Integer.parseInt(st.nextToken());if (b[i] == 0) has0 = true;else has1 = true;}boolean isSorted = true;for (int i = 0; i < n - 1; i++) {if (a[i] > a[i + 1]) {isSorted = false;break;}}if (isSorted) {out.println("Yes");} else {if (has0 && has1) {out.println("Yes");} else {out.println("No");}}}out.flush();out.close();}}